#!/usr/bin/env bash
# ==============================================================================
# Multi-Layer Security Evaluation Framework (MSEF)
# Script: scripts/measure-mbr-fuzz.sh
# Purpose: Empirically measure Manifest Blocking Rate (MBR) against a large-scale
#          corpus generated by the manifest mutation fuzzer.
# ==============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

source "${PROJECT_ROOT}/scripts/lib/common.sh"
source "${PROJECT_ROOT}/scripts/lib/output.sh"

CORPUS_DIR="${PROJECT_ROOT}/results/fuzzed-manifests"
LEDGER="${CORPUS_DIR}/manifest_ground_truth.tsv"
RESULTS_DIR="${PROJECT_ROOT}/results"
JSON_DIR="${RESULTS_DIR}/json"
TXT_DIR="${RESULTS_DIR}/txt"
LOGS_DIR="${RESULTS_DIR}/logs"

mkdir -p "${JSON_DIR}" "${TXT_DIR}" "${LOGS_DIR}"

DETAILS_LOG="${LOGS_DIR}/mbr-fuzz-details.log"
OUTPUT_JSON="${JSON_DIR}/mbr.json"
OUTPUT_TXT="${TXT_DIR}/mbr.txt"

TOTAL_CASES=${1:-100}

# 1. Generate corpus if missing or if count mismatch
log_info "Generating mutated manifest test suite (N=${TOTAL_CASES})..."
python3 "${PROJECT_ROOT}/scripts/fuzz_manifests.py" --count "${TOTAL_CASES}" --outdir "${CORPUS_DIR}"

echo "=== MSEF MBR Mutation Fuzzing Log $(date -u +"%Y-%m-%dT%H:%M:%SZ") ===" > "${DETAILS_LOG}"

# 2. Iterate and apply server-side admission evaluation
BLOCKED_COUNT=0
ALLOWED_COUNT=0

log_info "Evaluating admission controller webhooks (Server Dry-Run)..."

while IFS=$'\t' read -r FILENAME MANIFEST_TYPE CATEGORY; do
  [[ "${FILENAME}" == "file_name" ]] && continue
  
  FILEPATH="${CORPUS_DIR}/${FILENAME}"
  [[ ! -f "${FILEPATH}" ]] && continue

  # Execute server-side dry run to test admission webhooks
  APPLY_OUTPUT=""
  if APPLY_OUTPUT=$(kubectl apply --dry-run=server -f "${FILEPATH}" 2>&1); then
    # Allowed through admission
    ALLOWED_COUNT=$((ALLOWED_COUNT + 1))
    echo "[BYPASS] File: ${FILENAME} | Type: ${MANIFEST_TYPE} | Mutation: ${CATEGORY}" >> "${DETAILS_LOG}"
  else
    # Blocked by Gatekeeper, Kyverno, or PSA
    BLOCKED_COUNT=$((BLOCKED_COUNT + 1))
    echo "[BLOCKED] File: ${FILENAME} | Type: ${MANIFEST_TYPE} | Mutation: ${CATEGORY}" >> "${DETAILS_LOG}"
  fi

done < "${LEDGER}"

# 3. Metric Calculations
TOTAL_EVALUATED=$((BLOCKED_COUNT + ALLOWED_COUNT))
if [[ ${TOTAL_EVALUATED} -eq 0 ]]; then
  TOTAL_EVALUATED=1
fi

MBR=$(awk "BEGIN {printf \"%.4f\", ${BLOCKED_COUNT} / ${TOTAL_EVALUATED}}")
MBR_PERCENT=$(awk "BEGIN {printf \"%.2f\", ${MBR} * 100}")

# 4. Emit Standardized Deliverables
cat <<EOF > "${OUTPUT_JSON}"
{
  "metric": "MBR",
  "score": ${MBR},
  "percentage": ${MBR_PERCENT},
  "blocked_manifests": ${BLOCKED_COUNT},
  "allowed_manifests": ${ALLOWED_COUNT},
  "total_tested": ${TOTAL_EVALUATED},
  "test_mode": "mutation_fuzzing",
  "timestamp": "$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
}
EOF

cat <<EOF > "${OUTPUT_TXT}"
Metric: MBR
Score: ${MBR}
Percentage: ${MBR_PERCENT}%
Blocked: ${BLOCKED_COUNT}
Allowed (Bypassed): ${ALLOWED_COUNT}
Total Tested: ${TOTAL_EVALUATED}
EOF

echo ""
log_success "MBR Evaluation Complete!"
echo "--------------------------------------------------------"
echo "  Manifest Blocking Rate (MBR): ${MBR} (${MBR_PERCENT}%)"
echo "  Blocked:                     ${BLOCKED_COUNT}/${TOTAL_EVALUATED}"
echo "  Bypassed:                    ${ALLOWED_COUNT}/${TOTAL_EVALUATED}"
echo "--------------------------------------------------------"
echo "  Details Log: ${DETAILS_LOG}"
echo "  Output JSON: ${OUTPUT_JSON}"
echo "--------------------------------------------------------"